// Runs as root before the provisioning script has been downloaded. No curl/wget prerequisite.
const char *UBUNTU_BOOTSTRAP = R"CK(set -eu; export DEBIAN_FRONTEND=noninteractive NEEDRESTART_MODE=a; apt() { apt-get -o DPkg::Lock::Timeout=600 -o Dpkg::Options::=--force-confdef -o Dpkg::Options::=--force-confold -y "$@"; }; install_curl() { apt update || echo 'apt index update failed; trying cached lists' >&2; apt --fix-missing install curl ca-certificates && return 0; dpkg --configure -a || echo "dpkg still needs dependency repair" >&2; apt --fix-broken install || return 1; dpkg --configure -a || return 1; apt update || true; apt --fix-missing install curl ca-certificates; }; command -v curl >/dev/null 2>&1 || install_curl; f=$(mktemp); trap 'rm -f "$f"' EXIT; download() { curl --retry 3 --connect-timeout 15 -fsSL "$1" -o "$f"; }; if ! download "$1"; then echo 'Download failed; repairing curl and certificates before retrying' >&2; install_curl; download "$1"; fi; [ -s "$f" ] || { echo 'Provisioning download is empty' >&2; exit 1; }; bash "$f")CK";
